# ---------------------------------------------------------------- geometry
# Cell x = row*9 + col.  Wall index: orientation*64 + row*8 + col (0=H, 1=V).
FULL = (1 << 81) - 1
NT = []                     # NT[x][open4] -> tuple of neighbours
INIT_OPEN = [0] * 81        # 4-bit open mask per cell: 1=N 2=S 4=W 8=E
WALL_EDGES = [None] * 128   # wall -> ((a, b), (a2, b2))
WALL_TOG = [None] * 128     # wall -> ((cell, bit) x4) open-mask toggles
WALL_AND = [None] * 128     # wall -> and-masks for (openN, openS, openE, openW)
WALL_CONF = [0] * 128       # wall -> bitmask of walls it makes illegal (+ itself)
EDGE_WALLS = {}             # a*81+b -> walls cutting the edge a-b
EDGE_WMASK = {}             # a*81+b -> bitmask of those walls
EDGE_WOTHER = {}            # a*81+b -> ((w, u, t), ...): same walls with their other edge
WALL_CELLS = [None] * 128   # wall -> the four cells it touches
INIT_N = INIT_S = INIT_E = INIT_W = 0
ZW = []                     # zobrist: walls
ZP = []                     # zobrist: [player][cell]
ZN = []                     # zobrist: walls left of player 0
ZD = []                     # zobrist: [goal_row][cell] for the distance cache
ZSIDE = 0


def _init_geometry():
    global INIT_N, INIT_S, INIT_E, INIT_W, ZSIDE
    for x in range(81):
        r, c = divmod(x, 9)
        m = 0
        if r > 0:
            m |= 1
            INIT_N |= 1 << x
        if r < 8:
            m |= 2
            INIT_S |= 1 << x
        if c > 0:
            m |= 4
            INIT_W |= 1 << x
        if c < 8:
            m |= 8
            INIT_E |= 1 << x
        INIT_OPEN[x] = m
        row = []
        for k in range(16):
            nb = []
            if k & 1:
                nb.append(x - 9)
            if k & 2:
                nb.append(x + 9)
            if k & 4:
                nb.append(x - 1)
            if k & 8:
                nb.append(x + 1)
            row.append(tuple(nb))
        NT.append(row)
    for r in range(8):
        for c in range(8):
            a = r * 9 + c
            h = r * 8 + c
            v = 64 + h
            WALL_EDGES[h] = ((a, a + 9), (a + 1, a + 10))
            WALL_EDGES[v] = ((a, a + 1), (a + 9, a + 10))
            WALL_TOG[h] = ((a, 2), (a + 1, 2), (a + 9, 1), (a + 10, 1))
            WALL_TOG[v] = ((a, 8), (a + 9, 8), (a + 1, 4), (a + 10, 4))
            WALL_AND[h] = (FULL ^ ((1 << (a + 9)) | (1 << (a + 10))),
                           FULL ^ ((1 << a) | (1 << (a + 1))), FULL, FULL)
            WALL_AND[v] = (FULL, FULL, FULL ^ ((1 << a) | (1 << (a + 9))),
                           FULL ^ ((1 << (a + 1)) | (1 << (a + 10))))
            ch = (1 << h) | (1 << v)
            cv = ch
            if c > 0:
                ch |= 1 << (h - 1)
            if c < 7:
                ch |= 1 << (h + 1)
            if r > 0:
                cv |= 1 << (v - 8)
            if r < 7:
                cv |= 1 << (v + 8)
            WALL_CONF[h] = ch
            WALL_CONF[v] = cv
    for w in range(128):
        e1, e2 = WALL_EDGES[w]
        for (a, b), (u, t) in ((e1, e2), (e2, e1)):
            EDGE_WALLS.setdefault(a * 81 + b, []).append(w)
            EDGE_WALLS.setdefault(b * 81 + a, []).append(w)
            EDGE_WOTHER.setdefault(a * 81 + b, []).append((w, u, t))
            EDGE_WOTHER.setdefault(b * 81 + a, []).append((w, u, t))
    for k in list(EDGE_WALLS):
        EDGE_WALLS[k] = tuple(EDGE_WALLS[k])
        EDGE_WOTHER[k] = tuple(EDGE_WOTHER[k])
        EDGE_WMASK[k] = sum(1 << w for w in EDGE_WALLS[k])
    for w in range(128):
        (a, b), (c, d) = WALL_EDGES[w]
        WALL_CELLS[w] = (a, b, c, d)
    rnd = Random(20240917)
    g = rnd.getrandbits
    ZW.extend(g(62) for _ in range(128))
    ZP.append([g(62) for _ in range(81)])
    ZP.append([g(62) for _ in range(81)])
    ZN.extend(g(62) for _ in range(32))
    for _ in range(9):
        ZD.append([g(62) for _ in range(81)])
    ZSIDE = g(62)


_init_geometry()

