from operator import mul as _mul  # noqa: E402


def _wall_ends(w):
    o, r, c = w >> 6, (w & 63) >> 3, w & 7
    if o == 0:
        return {(r + 1, c), (r + 1, c + 2)}, (r + 1, c + 1)
    return {(r, c + 1), (r + 2, c + 1)}, (r + 1, c + 1)


def _init_policy():
    global TAB, TAB2, EMB, EB, OUT, OB
    E = [_wall_ends(w) for w in range(128)]
    for w in range(128):
        m = 0
        e, mid = E[w]
        for v in range(128):
            if v != w:
                e2, mid2 = E[v]
                if e & e2 or mid in e2 or mid2 in e or mid == mid2:
                    m |= 1 << v
        WALL_ADJ[w] = m
    if POLICY_KIND == "none" or not USE_POLICY:
        return
    import base64
    import zlib

    def dec(b, s):
        raw = zlib.decompress(base64.b64decode(b))
        return [((c ^ 128) - 128) * s for c in raw]
    if POLICY_KIND in ("tables", "both"):
        TAB = dec(TAB_B, TAB_S)
        TAB2 = dec(TAB2_B, TAB2_S)
    if POLICY_KIND in ("mlp", "both"):
        H = POLICY_H
        e = dec(EMB_B, EMB_S)
        EMB = [e[i * H:(i + 1) * H] for i in range(NC)]
        EB = dec(EB_B, EB_S)
        o = dec(OUT_B, OUT_S)
        OUT = [o[i * H:(i + 1) * H] for i in range(NOUT)]
        OB = dec(OB_B, OB_S)


def flip_mask(m):
    out = 0
    w = 0
    while m:
        if m & 1:
            out |= 1 << FLIPW[w]
        m >>= 1
        w += 1
    return out


_init_policy()

