def _bfs(adj, goal_row):
    """Distance of every cell to goal_row, ignoring pawns; -1 = unreachable."""
    dist = [-1] * 81
    frontier = list(range(goal_row * 9, goal_row * 9 + 9))
    for x in frontier:
        dist[x] = 0
    d = 0
    while frontier:
        d += 1
        nxt = []
        for x in frontier:
            for y in adj[x]:
                if dist[y] < 0:
                    dist[y] = d
                    nxt.append(y)
        frontier = nxt
    return dist


_RACE = {}      # (wall zobrist, my goal) -> _Race


class _Race:
    """Exact solver for the pure race (no walls left) on one fixed wall set.

    State = (cell of player 0, cell of player 1, side to move); moves are
    steps, jumps and pass.  Alpha-beta with a transposition table; iterative
    deepening on the horizon (plies).  Values: WIN-n win in n plies,
    -(WIN-n) loss, 0 no forced result within the horizon (a draw: the
    retrograde table agrees on logged positions).  Exactness: a non-zero TT
    value is a true forced result and is reused only when its length fits the
    current horizon; a zero only for horizons <= the one searched.  The far-
    apart test (pawn distance > race length) returns the distance formula,
    which is exact when the pawns cannot meet before the race is over.
    """
    __slots__ = ("adj", "F", "tt", "D", "nodes", "limit", "aborted", "deadline")

    def __init__(self):
        self.tt = {}
        self.D = [None] * 81
        self.nodes = 0
        self.limit = 0
        self.aborted = False
        self.adj = None
        self.F = None
        self.deadline = 0.0

    def pdist(self, a):
        D = self.D[a]
        if D is None:
            adj = self.adj
            D = [99] * 81
            D[a] = 0
            fr = [a]
            d = 0
            while fr:
                d += 1
                nx = []
                for x in fr:
                    for y in adj[x]:
                        if D[y] == 99:
                            D[y] = d
                            nx.append(y)
                fr = nx
            self.D[a] = D
        return D

    def solve(self, p0, p1, side, limit, deadline):
        """Value for `side` to move, or None if the node limit / deadline hit."""
        F = self.F
        dp = F[side][p0 if side == 0 else p1]
        dq = F[1 - side][p1 if side == 0 else p0]
        self.nodes = 0
        self.limit = limit
        self.aborted = False
        self.deadline = deadline
        hmax = 2 * (dp if dp > dq else dq) + 6
        h = 2 * (dp if dp < dq else dq) + 1
        if h > hmax:
            h = hmax
        while True:
            v = self._ab(p0, p1, side, h, -WIN - 1, WIN + 1)
            if self.aborted:
                return None
            if v != 0 or h >= hmax:
                return v
            h += 4
            if h > hmax:
                h = hmax

    def _ab(self, p0, p1, side, h, alpha, beta):
        self.nodes += 1
        if self.nodes > self.limit or (self.nodes & 127) == 0 and _perf() > self.deadline:
            self.aborted = True
            return 0
        F = self.F
        if side == 0:
            a = p0
            b = p1
        else:
            a = p1
            b = p0
        Fs = F[side]
        dp = Fs[a]
        dq = F[1 - side][b]
        if dp <= dq:
            T = 2 * dp - 1
        else:
            T = 2 * dq
        if self.pdist(a)[b] > T:
            if dp <= dq:
                v = WIN - T
            else:
                v = T - WIN
            if T > h:                   # longer than the horizon: unknown
                return 0
            return v
        if h <= 0:
            return 0
        key = (p0, p1, side)
        e = self.tt.get(key)
        if e is not None:
            v, flag, eh = e
            if (eh >= h) if v == 0 else (WIN - (v if v > 0 else -v) <= h):
                if flag == 0:
                    return v
                if flag == 1:
                    if v >= beta:
                        return v
                    if v > alpha:
                        alpha = v
                elif v <= alpha:
                    return v
                elif v < beta:
                    beta = v
        alpha0 = alpha
        adj = self.adj
        mv = []
        for y in adj[a]:
            if y != b:
                mv.append(y)
            else:
                j = b + b - a
                if j in adj[b]:
                    mv.append(j)
                else:
                    for z in adj[b]:
                        if z != a:
                            mv.append(z)
        mv.sort(key=lambda y: Fs[y] if Fs[y] >= 0 else 99)
        best = -WIN - 1
        done = False
        for y in mv:
            if Fs[y] == 0:
                best = WIN - 1
                done = True
                break
            if side == 0:
                v = -self._ab(y, p1, 1, h - 1, -beta, -alpha)
            else:
                v = -self._ab(p0, y, 0, h - 1, -beta, -alpha)
            if v > 0:
                v -= 1
            elif v < 0:
                v += 1
            if v > best:
                best = v
                if v > alpha:
                    alpha = v
                    if v >= beta:
                        done = True
                        break
        if not done:                    # pass
            v = -self._ab(p0, p1, 1 - side, h - 1, -beta, -alpha)
            if v > 0:
                v -= 1
            elif v < 0:
                v += 1
            if v > best:
                best = v
        if self.aborted:
            return 0
        self.tt[key] = (best, 1 if best >= beta else (2 if best <= alpha0 else 0), h)
        return best


class _Timeout(Exception):
    pass


def _search(pos, goal, wl, walls, root_pawn, legal_wall_set, deadline, revisit=None):
    """Internal player 0 is us.  Returns the chosen move: cell or 100+wall."""
    opn = list(INIT_OPEN)
    adj = [NT[x][opn[x]] for x in range(81)]
    oN, oS, oE, oW = INIT_N, INIT_S, INIT_E, INIT_W
    blocked = 0
    wz = 0
    for w in walls:
        for x, bit in WALL_TOG[w]:
            if opn[x] & bit:
                opn[x] ^= bit
                adj[x] = NT[x][opn[x]]
        aN, aS, aE, aW = WALL_AND[w]
        oN &= aN
        oS &= aS
        oE &= aE
        oW &= aW
        blocked |= WALL_CONF[w]
        wz ^= ZW[w]

    pos = list(pos)
    wl = list(wl)
    g0, g1 = goal
    GM = ((0x1FF << (g0 * 9)), (0x1FF << (g1 * 9)))
    FC = (_FC.setdefault(g0, {}), _FC.setdefault(g1, {}))
    for d_ in FC:
        if len(d_) > FC_LIMIT:
            d_.clear()
    if len(_DC) > DC_LIMIT:
        _DC.clear()
    DC = _DC
    ZDP = (ZD[g0], ZD[g1])
    ZP0, ZP1 = ZP
    TT = {}
    nullok_block = [0]
    onpath = set()
    WT = WALL_TABLE if WALL_TABLE else [WALL_VALUE * i_ for i_ in range(40)]
    WD = WALL_BY_DIST
    TEX_ = USE_TEXEL
    TEMPO_ = TEXEL_TEMPO if TEX_ else TEMPO
    WFB_ = WALL_FRONTIER_BONUS
    RS_ = USE_RACE_SOLVER
    POL_ = USE_POLICY
    PLMR_ = POL_ and POLICY_LMR
    PTAB_ = POLICY_TAB_PLY if POL_ else -1
    PMLP_ = POLICY_MLP_PLY
    PG1_ = POLICY_GAP1
    PG2_ = POLICY_GAP2
    PLD_ = POLICY_LMR_DEPTH
    BOOK_ = USE_LOST_SEARCH
    PLUGT_ = USE_PLUGT
    PTC = {}                 # plug-threat cache per search: (walls, blocked pawn, plugger, side)
    GEN = {}
    QG = {}         # wz ^ ZDP[q][b] -> ([(w, nq)], mask): walls cutting q's path from b (path order)
    MG = {}         # wz ^ ZDP[p][a] -> mask of walls crossing one of p's shortest paths from a
    rN, rS, rE, rW = oN, oS, oE, oW      # root open masks
    DEAD = ([None] * 128, [None] * 128)
    RC = ({}, {})
    hist = [0] * 128
    killers = [[-1, -1] for _ in range(MAX_DEPTH + 8)]
    nodes = 0
    wm = [0]                      # placed walls as a 128-bit mask
    for w in walls:
        wm[0] |= 1 << w
    PC = {}                       # policy cache: node key -> {move: logit}
    pstat = [0, 0]                # policy evaluations (tables nodes, mlp nodes)

    def plogits(p, a, b, wp, wq, dp, dq, cands, mlp):
        """Policy logits for cands = [(mv, g, nq, np_, isdef)], mover p.

        The frame is normalised so that the mover heads to row 0 (`feat.py`)."""
        flip = goal[p] == 8
        mask = wm[0]
        if flip:
            a = FLIPC[a]
            b = FLIPC[b]
            mask = flip_mask(mask)
        T = TAB2 if (mlp and POLICY_H) else TAB
        dd = (dp - dq if -8 <= dp - dq <= 8 else (-8 if dp - dq < -8 else 8)) + 8
        wa = wp if wp <= 10 else 10
        wb = wq if wq <= 10 else 10
        wbase = T[WWB + wb] + T[WDD + dd]
        pbase = T[PWA + wa] + T[PWB + wb] + T[PDD + dd]
        wwa = WWA + (wa - 1 if wa >= 1 else 0)
        h = None
        if mlp and POLICY_H:
            pstat[1] += 1
            E = EMB
            h = E[CA + a][:]
            for row in (E[CB + b], E[CWA + wa], E[CWB + wb],
                        E[CDP + (dp if dp <= 16 else 16)], E[CDQ + (dq if dq <= 16 else 16)]):
                h = [x + y for x, y in zip(h, row)]
            m = mask
            w = 0
            while m:
                if m & 1:
                    h = [x + y for x, y in zip(h, E[CW + w])]
                m >>= 1
                w += 1
            h = [x + y if x + y > 0 else 0.0 for x, y in zip(h, EB)]
        else:
            pstat[0] += 1
        out = []
        for mv, g, nq, np_, isdef in cands:
            gg = (g if -3 <= g <= 8 else (-3 if g < -3 else 8)) + 3
            if mv >= 100:
                w = mv - 100
                if flip:
                    w = FLIPW[w]
                q1 = nq - dq
                q2 = np_ - dp
                s = (wbase + T[WB + w * 81 + b] + T[WA + w * 81 + a] + T[WG + gg]
                     + T[WQ + (q1 if q1 <= 8 else 8)] + T[WP + (q2 if q2 <= 8 else 8)]
                     + T[wwa + w * 10] + T[WADJ + (1 if mask & WALL_ADJ[w] else 0)]
                     + T[WDEF + (1 if isdef else 0)])
                slot = 81 + w
            else:
                y = FLIPC[mv] if flip else mv
                s = pbase + T[PB + y * 81 + b] + T[PA + y * 81 + a] + T[PG + gg]
                slot = y
            if h is not None:
                s += OB[slot] + sum(map(_mul, h, OUT[slot]))
            out.append(s)
        return out

    def porder(p, a, b, wp, wq, dp, dq, lst, mlp, key, tm, k0, k1, start):
        """Re-sort lst[start:] by policy score; entries (key, mv, nq, np_, g, static)."""
        rest = lst[start:]
        cache = PC.get(key)
        if cache is not None:
            for e in rest:
                if e[1] not in cache:
                    cache = None
                    break
        if cache is None:
            cands = []
            for e in rest:
                mv = e[1]
                st = e[5]
                if st >= 50000000:
                    st -= 100000000
                elif mv == k0 or mv == k1:
                    st -= 15000
                if mv >= 100:
                    g = e[2] - dq - e[3] + dp
                    cands.append((mv, g, e[2], e[3], 0))
                else:
                    cands.append((mv, st // 10000, dq, dp, 0))
            lg = plogits(p, a, b, wp, wq, dp, dq, cands, mlp)
            cache = {}
            for e, v in zip(rest, lg):
                cache[e[1]] = v
            PC[key] = cache
        out = []
        top = max(cache.values())
        for e in rest:
            mv = e[1]
            v = cache.get(mv)
            if v is None:
                v = -20.0
            gap = top - v
            s = int(v * POLICY_SCALE)
            if mv == tm:
                s += 100000000
            elif mv == k0 or mv == k1:
                s += POLICY_KILLER
            if mv >= 100:
                s += hist[mv - 100] * POLICY_HIST // 1000
            out.append((s, mv, e[2], e[3], gap, e[5]))
        out.sort(reverse=True)
        return lst[:start] + out


    def field(gi):
        F = FC[gi].get(wz)
        if F is None:
            F = _bfs(adj, goal[gi])
            FC[gi][wz] = F
        return F

    def child_field(F, w, gi):
        """Field after wall w was placed (adj / wz already updated).

        Incremental: cells that lost every parent are collected (phase 1) and
        only those are re-labelled from their unaffected neighbours (phase 2).
        A wall that leaves every cell a parent leaves every distance alone, so
        the cached field for the new wall set (when present) equals F.
        """
        G = FC[gi].get(wz)
        if G is not None:
            return G
        adj_ = adj
        (x1, y1), (x2, y2) = WALL_EDGES[w]
        dx = F[x1]
        dy = F[y1]
        if dx != dy:
            if dx > dy:
                hi = x1
                t = dy
            else:
                hi = y1
                t = dx
            for n in adj_[hi]:
                if F[n] == t:
                    break
            else:
                G = F[:]
                G[hi] = -2
                aff = [hi]
        dx = F[x2]
        dy = F[y2]
        if dx != dy:
            if dx > dy:
                hi = x2
                t = dy
            else:
                hi = y2
                t = dx
            if G is None:
                for n in adj_[hi]:
                    if F[n] == t:
                        break
                else:
                    G = F[:]
                    G[hi] = -2
                    aff = [hi]
            elif G[hi] != -2:
                for n in adj_[hi]:
                    if G[n] == t:
                        break
                else:
                    G[hi] = -2
                    aff.append(hi)
        if G is None:
            return F
        for x in aff:                   # grows while we scan it
            t = F[x]
            d1 = t + 1
            for y in adj_[x]:
                if G[y] == d1:
                    for n in adj_[y]:
                        if G[n] == t:
                            break
                    else:
                        G[y] = -2
                        aff.append(y)
        # Relabel by detour: an affected cell at old level f gets f + k in
        # round k when a neighbour already carries f + k - 1.  Lower cells go
        # first inside a round, so same-round dependencies resolve in order.
        # Two rounds without progress mean the rest is cut off.
        rem = sorted(aff, key=F.__getitem__)
        k = 0
        idle = 0
        while rem:
            nxt = []
            for x in rem:
                f1 = F[x] + k
                for n in adj_[x]:
                    if G[n] == f1:
                        G[x] = f1 + 1
                        break
                else:
                    nxt.append(x)
            if len(nxt) == len(rem):
                idle += 1
                if idle == 2:
                    break
            else:
                idle = 0
            rem = nxt
            k += 1
        for x in rem:
            G[x] = -1
        FC[gi][wz] = G
        return G

    def changed(F, w):
        """Would wall w (not yet placed) alter distance field F at all?"""
        for u, t in WALL_EDGES[w]:
            du = F[u]
            dt_ = F[t]
            if du == dt_:
                continue
            if du > dt_:
                hi = u
                lo = t
                tv = dt_
            else:
                hi = t
                lo = u
                tv = du
            for n in adj[hi]:
                if n != lo and F[n] == tv:
                    break
            else:
                return True
        return False

    def wdist(w, x, gi, F=None):
        """Distance of cell x to goal gi if wall w were added; -1 if cut off.
        F is the current field for gi (looked up when not given)."""
        k = wz ^ ZW[w] ^ ZDP[gi][x]
        d = DC.get(k)
        if d is not None:
            return d
        if F is None:
            F = field(gi)
        dx = F[x]
        if dx < 0:
            DC[k] = -1
            return -1
        c0, c1, c2, c3 = WALL_CELLS[w]
        m = F[c0]
        L = m
        t = F[c1]
        if t < m:
            m = t
        elif t > L:
            L = t
        t = F[c2]
        if t < m:
            m = t
        elif t > L:
            L = t
        t = F[c3]
        if t < m:
            m = t
        elif t > L:
            L = t
        if m < 0:
            m = 0
        if dx <= m:
            d = dx                  # cells at level <= m keep their distance
        else:
            # Flood from x under the new walls until it meets cells the wall
            # cannot have changed: all of level <= m, and level m+1 except the
            # upper cells of the two cut edges (see gen_walls).
            R = levels(gi, dx)
            (u1, t1), (u2, t2) = WALL_EDGES[w]
            hm = 0
            du = F[u1]
            dt_ = F[t1]
            if du > dt_:
                hm = 1 << u1
            elif dt_ > du:
                hm = 1 << t1
            du = F[u2]
            dt_ = F[t2]
            if du > dt_:
                hm |= 1 << u2
            elif dt_ > du:
                hm |= 1 << t2
            stop = R[m + 1] & ~hm
            aN, aS, aE, aW = WALL_AND[w]
            n_ = oN & aN
            s_ = oS & aS
            e_ = oE & aE
            w_ = oW & aW
            v = 1 << x
            d = m
            while not (v & stop):
                nv = v | ((v & n_) >> 9) | ((v & s_) << 9) | ((v & e_) << 1) | ((v & w_) >> 1)
                if nv == v:
                    d = -1
                    break
                v = nv
                d += 1
            if d >= 0 and not (v & R[m]):
                d += 1
        DC[k] = d
        return d

    def mkdead(w, gi):
        """Cells cut off from goal gi by wall w already in the root position.
        More walls never reconnect them, so this holds in the whole tree."""
        aN, aS, aE, aW = WALL_AND[w]
        n_ = rN & aN
        s_ = rS & aS
        e_ = rE & aE
        w_ = rW & aW
        v = GM[gi]
        while True:
            nv = v | ((v & n_) >> 9) | ((v & s_) << 9) | ((v & e_) << 1) | ((v & w_) >> 1)
            if nv == v:
                break
            v = nv
        v ^= FULL
        DEAD[gi][w] = v
        return v

    def levels(gi, need):
        """R[k] = bitboard of cells within k steps of goal gi (current walls)."""
        R = RC[gi].get(wz)
        if R is None:
            R = [GM[gi]]
            RC[gi][wz] = R
        v = R[-1]
        n_ = oN
        s_ = oS
        e_ = oE
        w_ = oW
        for _ in range(need + 1 - len(R)):
            v = v | ((v & n_) >> 9) | ((v & s_) << 9) | ((v & e_) << 1) | ((v & w_) >> 1)
            R.append(v)
        return R

    def plugged(x, y, gi):
        """True if a pawn on x (goal gi) cannot reach its goal while a pawn stays on y (jumps over y allowed)."""
        keep = FULL ^ (1 << y)
        n_ = oN
        s_ = oS
        e_ = oE
        w_ = oW
        gm = GM[gi]
        ay = adj[y]
        v = 1 << x
        while True:
            while True:
                nv = (v | ((v & n_) >> 9) | ((v & s_) << 9) | ((v & e_) << 1) | ((v & w_) >> 1)) & keep
                if nv == v:
                    break
                v = nv
            if v & gm:
                return False
            add = 0
            for z in ay:
                if (v >> z) & 1:
                    j = y + y - z
                    if j in ay:
                        add |= 1 << j
                    else:
                        for t in ay:
                            if t != z:
                                add |= 1 << t
            nv = v | (add & keep)
            if nv == v:
                return True
            v = nv

    def plug_threat(x, y, Fx, gi):
        """The pawn on y can reach a cut cell of x's routes (to goal gi) no later than x reaches it."""
        d = Fx[x]
        if d <= 1:
            return False
        path = []
        c = x
        k = 0
        while Fx[c] > 1:
            fc = Fx[c] - 1
            for z in adj[c]:
                if Fx[z] == fc:
                    c = z
                    break
            else:
                return False
            k += 1
            path.append((c, k))
        if not path:
            return False
        n_ = oN
        s_ = oS
        e_ = oE
        w_ = oW
        v = 1 << y
        dy = 0
        todo = path
        while todo:
            rest = []
            for c, k in todo:
                if (v >> c) & 1:
                    if plugged(x, c, gi):
                        return True
                elif dy < k:
                    rest.append((c, k))
            if not rest:
                return False
            nv = v | ((v & n_) >> 9) | ((v & s_) << 9) | ((v & e_) << 1) | ((v & w_) >> 1)
            if nv == v:
                return False
            v = nv
            dy += 1
            todo = rest
        return False

    def ev(ds, dt, ws, wt, ply):
        """Static value for the side to move (distance ds, walls ws)."""
        if ds <= 1:
            return WIN - ply
        if wt == 0 and ds <= dt:
            return RACE - 10 * ds
        if ws == 0 and dt < ds:
            return 10 * dt - RACE
        if TEX_:
            return STEP_VALUE * (dt - ds) + WD[ds + dt] * (ws - wt) + TEMPO_
        return STEP_VALUE * (dt - ds) + WT[ws] - WT[wt] + TEMPO_

    def exact(p, Fp, Fq, limit):
        """Exact pure-race value for p to move (RACE scale), None if over budget."""
        k = (wz, g0)
        S = _RACE.get(k)
        if S is None:
            if len(_RACE) > RACE_LIMIT:
                _RACE.clear()
            S = _Race()
            _RACE[k] = S
        S.adj = adj
        S.F = (Fp, Fq) if p == 0 else (Fq, Fp)
        v = S.solve(pos[0], pos[1], p, limit, deadline)
        if v is None:
            return None
        if v > 0:
            return RACE - 10 * (WIN - v)
        if v < 0:
            return 10 * (WIN + v) - RACE
        return 0

    def gen_walls(p, Fp, Fq, a, b, dp, dq, key):
        """Walls for player p that cut q's shortest path: [(gain-loss, w, nq, np)]."""
        ap_ = AP[0]
        if ap_:
            key ^= ZAPK
        out = GEN.get(key)
        if out is not None:
            return out
        q = 1 - p
        adj_ = adj
        zb = wz ^ ZDP[q][b]
        zq = zb ^ ZAPK if ap_ else zb
        Qm = QG.get(zq)
        if Qm is None:
            # The part that depends only on the walls and on q's pawn: every wall
            # crossing q's shortest path, with q's new distance (-1 = cut off).
            Q = []
            qm = 0
            qmine = 0           # walls crossing this path: q's own "mine" mask
            seen = blocked
            deadq = DEAD[q]
            FCq = FC[q]
            R = None
            B = None            # B[s] = cells within s steps of b under the current walls
            ZW_ = ZW
            WA = WALL_AND
            WC = WALL_CELLS
            EWO = EDGE_WOTHER
            EM = EDGE_WMASK
            n0 = oN
            s0 = oS
            e0 = oE
            w0 = oW
            x = b
            d = dq
            while d > 0:
                d -= 1
                for y in adj_[x]:
                    if Fq[y] == d:
                        break
                else:
                    break
                ek = x * 81 + y
                qmine |= EM[ek]
                # changed(Fq, w) inlined.  The path edge x->y is shared by both
                # walls: x is the upper cell, y its parent at level d.  x keeps
                # a parent iff it has another level-d neighbour.
                for n in adj_[x]:
                    if n != y and Fq[n] == d:
                        ch0 = False
                        break
                else:
                    ch0 = True
                for w, u2, t2 in EWO[ek]:
                    bw = 1 << w
                    if seen & bw:
                        continue
                    seen |= bw
                    ch = ch0
                    if not ch:
                        du = Fq[u2]
                        dt_ = Fq[t2]
                        if du != dt_:
                            if du > dt_:
                                hi = u2
                                lo = t2
                                tv = dt_
                            else:
                                hi = t2
                                lo = u2
                                tv = du
                            for n in adj_[hi]:
                                if n != lo and Fq[n] == tv:
                                    break
                            else:
                                ch = True
                    if ch:
                        k = zb ^ ZW_[w]
                        nq = DC.get(k)
                        if nq is None:
                            G_ = FCq.get(wz ^ ZW_[w])
                            if G_ is not None:
                                nq = G_[b]        # the field after w is already known
                            else:
                                dm = deadq[w]
                                if dm is None:
                                    dm = mkdead(w, q)
                                if (dm >> b) & 1:
                                    nq = -1
                                else:
                                    # Flood from b under the new walls until it meets
                                    # cells whose distance the wall cannot have changed.
                                    # m / L = lowest / highest level among the wall's
                                    # cells.  Cells at level <= m are unchanged, and at
                                    # level m+1 only the upper cells of the two cut
                                    # edges can be (x is one; the other edge's is hm).
                                    # The first dq-L expansions cannot cross a cut
                                    # edge (one must stand on an endpoint, level <= L,
                                    # first), so they equal the old ball around b.
                                    c0, c1, c2, c3 = WC[w]
                                    m = Fq[c0]
                                    L = m
                                    t = Fq[c1]
                                    if t < m:
                                        m = t
                                    elif t > L:
                                        L = t
                                    t = Fq[c2]
                                    if t < m:
                                        m = t
                                    elif t > L:
                                        L = t
                                    t = Fq[c3]
                                    if t < m:
                                        m = t
                                    elif t > L:
                                        L = t
                                    if m < 0:
                                        m = 0
                                    if R is None:
                                        R = levels(q, dq)
                                    j = dq - L
                                    if j > 0:
                                        if B is None:
                                            B = [1 << b]
                                        v = B[-1]
                                        while len(B) <= j:
                                            v = v | ((v & n0) >> 9) | ((v & s0) << 9) | ((v & e0) << 1) | ((v & w0) >> 1)
                                            B.append(v)
                                        v = B[j]
                                        nq = m + j
                                    else:
                                        v = 1 << b
                                        nq = m
                                    hm = 1 << x
                                    du = Fq[u2]
                                    dt_ = Fq[t2]
                                    if du > dt_:
                                        hm |= 1 << u2
                                    elif dt_ > du:
                                        hm |= 1 << t2
                                    stop = R[m + 1] & ~hm
                                    aN, aS, aE, aW = WA[w]
                                    n_ = n0 & aN
                                    s_ = s0 & aS
                                    e_ = e0 & aE
                                    w_ = w0 & aW
                                    while not (v & stop):
                                        nv = v | ((v & n_) >> 9) | ((v & s_) << 9) | ((v & e_) << 1) | ((v & w_) >> 1)
                                        if nv == v:
                                            nq = -1
                                            break
                                        v = nv
                                        nq += 1
                                    if nq >= 0 and not (v & R[m]):
                                        nq += 1
                            DC[k] = nq
                        if nq < 0:
                            continue
                    else:
                        nq = dq
                    Q.append((w, nq))
                    qm |= bw
                x = y
            if ap_:
                # red-team: also the walls crossing q's OTHER shortest paths (route-closing
                # set-up walls).  They leave the first path intact, so q's distance is unchanged.
                fr = [b]
                vis = 1 << b
                while fr:
                    nx = []
                    for x in fr:
                        d = Fq[x] - 1
                        if d < 0:
                            continue
                        for y in adj_[x]:
                            if Fq[y] == d:
                                for w, u2, t2 in EWO[x * 81 + y]:
                                    bw = 1 << w
                                    if not (seen & bw):
                                        seen |= bw
                                        Q.append((w, dq))
                                        qm |= bw
                                if not (vis >> y) & 1:
                                    vis |= 1 << y
                                    nx.append(y)
                    fr = nx
            QG[zq] = (Q, qm)
            MG[zb] = qmine
        else:
            Q, qm = Qm
        # Walls crossing one of my own shortest paths; only those can cost me.
        za = wz ^ ZDP[p][a]
        mine = MG.get(za)
        if mine is None:
            mine = 0
            x = a
            d = dp
            while d > 0:
                d -= 1
                for y in adj_[x]:
                    if Fp[y] == d:
                        break
                else:
                    break
                mine |= EDGE_WMASK[x * 81 + y]
                x = y
            MG[za] = mine
        if mine & qm == 0:
            out = [(nq - dq, w, nq, dp) for w, nq in Q]
        else:
            out = []
            for w, nq in Q:
                np_ = dp
                if (mine >> w) & 1 and changed(Fp, w):
                    np_ = wdist(w, a, p, Fp)
                    if np_ < 0:
                        continue
                out.append((nq - dq - np_ + dp, w, nq, np_))
        GEN[key] = out
        return out

    WA_ = WALL_AND
    WCF_ = WALL_CONF
    WTG_ = WALL_TOG
    NT_ = NT
    ZW_ = ZW
    nlim = NODE_LIMIT
    WIN_ = WIN
    RACE_ = RACE
    INF_ = INF
    STEP_ = STEP_VALUE
    QD_ = QUIET_DEPTH
    NM_ = NULL_MOVE
    APLY_ = ALLPATH_PLY if ALLPATH else -1
    AP = [1 if ALLPATH else 0]     # all-path wall lists wanted by the node being expanded
    ZAPK = 0x5DEECE66D1234567

    def search(p, depth, alpha, beta, ply, Fp, Fq):
        nonlocal nodes, oN, oS, oE, oW, blocked, wz
        nodes += 1
        if nodes >= nlim or (nodes & 7) == 0 and _perf() > deadline:
            raise _Timeout()
        q = 1 - p
        a = pos[p]
        b = pos[q]
        dp = Fp[a]
        dq = Fq[b]
        wp = wl[p]
        wq = wl[q]

        nb = adj[a]
        if b in nb:
            moves = []
            for y in nb:
                if y != b:
                    moves.append(y)
                else:
                    nbb = adj[b]
                    j = b + b - a
                    if j in nbb:
                        moves.append(j)
                    else:
                        for z in nbb:
                            if z != a:
                                moves.append(z)
        else:
            moves = nb
        md = 99
        by = -1
        for y in moves:
            d = Fp[y]
            if d < md:
                md = d
                by = y
        if md == 0:
            return WIN_ - ply
        if PLUGT_ and (wp == 0 or wq == 0):
            e0 = ev(dp, dq, wp, wq, ply)
            if wp == 0 and e0 > 0 and dp < dq + 2:
                pk = (wz, a, b, p)
                t_ = PTC.get(pk)
                if t_ is None:
                    t_ = PTC[pk] = plug_threat(a, b, Fp, p)
                if t_:
                    return 0            # q can park on our cut cell first and pass: a draw at best
            if wq == 0 and e0 < 0 and dq < dp + 2:
                pk = (wz, b, a, q)
                t_ = PTC.get(pk)
                if t_ is None:
                    t_ = PTC[pk] = plug_threat(b, a, Fq, q)
                if t_:
                    return 0            # we can park on q's cut cell first and pass
        if wq == 0 or wp == 0:
            v = exact(p, Fp, Fq, EXACT_ROOT_NODES if ply <= 1 else EXACT_NODES) if RS_ else None
            if v is None:                   # solver off or over budget: distance formula
                if wq == 0 and md < dq:
                    return RACE_ - 10 * (md + 1)
                if wp == 0 and dq <= md:
                    return 10 * dq - RACE_
            elif wq == 0 and wp == 0:       # pure race: exact
                return v
            elif wq == 0 and v > 0:         # we win by racing; our walls can only help
                return v
            elif wp == 0 and v < 0:         # they win by racing; their walls can only help
                return v

        key = wz ^ ZP0[pos[0]] ^ ZP1[pos[1]] ^ ZN[wl[0]]
        if p:
            key ^= ZSIDE
        if key in onpath:
            return 0            # repetition inside the line: shuffling gains nothing
        e = TT.get(key)
        tm = -1
        alpha0 = alpha
        if e is not None:
            tm = e[3]
            if e[0] >= depth:
                f = e[1]
                v = e[2]
                if f == 0:
                    return v
                if f == 1:
                    if v >= beta:
                        return v
                    if v > alpha:
                        alpha = v
                elif v <= alpha:
                    return v
                elif v < beta:
                    beta = v

        if depth <= 1:
            # ---- frontier node: children are evaluated inline
            ply1 = ply + 1
            if by >= 0:
                best = None
                if RS_ and (wq == 0 or wp == 0):
                    pos[p] = by
                    v = exact(q, Fq, Fp, EXACT_NODES)
                    pos[p] = a
                    if v is not None:
                        if wq == 0 and v < 0:       # they (no walls) lose the race
                            best = -v
                        elif wp == 0 and v > 0:     # they win by racing
                            best = -v
                if best is None:
                    best = -ev(dq, md, wq, wp, ply1)
                bm = by
            else:
                best = -INF_
                bm = -1
            if best < beta and wp > 0:   # near-goal fix (_ng): keep blocking walls when a pawn is 1 step out
                wp1 = wp - 1
                # v = WFB_ - ev(nq, np_, wq, wp1, ply1) inlined for the wall children
                # (the frontier bonus is folded into the constants: zero cost when 0)
                win1 = WIN_ - ply1 - WFB_
                race1 = RACE_ - WFB_
                race2 = RACE_ + WFB_
                tcst = TEMPO_ - WFB_
                cst = WT[wq] - WT[wp1] + tcst
                wqp = wq - wp1
                AP[0] = ply <= APLY_
                for g, w, nq, np_ in gen_walls(p, Fp, Fq, a, b, dp, dq, key):
                    if g <= 0:
                        continue
                    if nq <= 1:
                        v = -win1
                    elif wp1 == 0 and nq <= np_:
                        v = 10 * nq - race1
                    elif wq == 0 and np_ < nq:
                        v = race2 - 10 * np_
                    elif TEX_:
                        v = STEP_ * (nq - np_) - WD[nq + np_] * wqp - tcst
                    else:
                        v = STEP_ * (nq - np_) - cst
                    if v > best:
                        best = v
                        bm = 100 + w
                        if v >= beta:
                            break
            if bm < 0:
                best = -ev(dq, dp, wq, wp, ply1)
            TT[key] = (1, 1 if best >= beta else (2 if best <= alpha0 else 0), best, bm)
            return best

        # ---- interior node
        if (NM_ and depth >= 3 and beta - alpha == 1 and beta < RACE_ - 1000
                and beta > 1000 - RACE_ and dq > 1 and not nullok_block[0]):
            if STEP_ * (dq - dp) + (WD[dp + dq] * (wp - wq) if TEX_ else WT[wp] - WT[wq]) + TEMPO_ >= beta:
                nullok_block[0] = 1
                v = -search(q, depth - 3, -beta, -beta + 1, ply + 1, Fq, Fp)
                nullok_block[0] = 0
                if v >= beta:
                    return v
        kl = killers[ply]
        k0 = kl[0]
        k1 = kl[1]
        lst = []
        for y in moves:
            s = (dp - Fp[y]) * 10000
            if y == tm:
                s += 100000000
            elif y == k0 or y == k1:
                s += 15000
            lst.append((s, y, 0, 0, 0, s))
        if wp > 0:
            quiet = depth >= QD_
            AP[0] = ply <= APLY_
            for g, w, nq, np_ in gen_walls(p, Fp, Fq, a, b, dp, dq, key):
                if nq == dq and not quiet:
                    continue
                mv = 100 + w
                s = g * 10000 - 7000 + hist[w]
                if mv == tm:
                    s += 100000000
                elif mv == k0 or mv == k1:
                    s += 15000
                lst.append((s, mv, nq, np_, 0, s))
        if not lst:
            return -search(q, depth - 1, -beta, -alpha, ply + 1, Fq, Fp)
        lst.sort(reverse=True)
        # ---- policy ordering (USE_POLICY): the entries' first field is replaced
        # by the policy score (TT move / killers keep a bonus); with POLICY_LAZY
        # the scoring waits until the first (TT) move has failed to cut off.
        use_pol = ply <= PTAB_ and len(lst) > 2
        pending = use_pol and POLICY_LAZY and tm >= 0 and lst[0][1] == tm
        if use_pol and not pending:
            lst = porder(p, a, b, wp, wq, dp, dq, lst, ply <= PMLP_, key, tm, k0, k1, 0)

        onpath.add(key)
        best = -INF_
        bm = -1
        i = 0
        nd = depth - 1
        ply1 = ply + 1
        n_lst = len(lst)
        while i < n_lst:
            if i == 1 and pending:
                lst = porder(p, a, b, wp, wq, dp, dq, lst, ply <= PMLP_, key, tm, k0, k1, 1)
            _, mv, nq, np_, gap, s = lst[i]
            if mv < 100:
                pos[p] = mv
                if i == 0:
                    v = -search(q, nd, -beta, -alpha, ply1, Fq, Fp)
                else:
                    r = nd
                    if i >= 3 and depth >= 3 and s < 10000:
                        r -= 1
                    if PLMR_ and depth >= PLD_ and gap >= PG1_:
                        r -= 1
                        if gap >= PG2_ and depth > PLD_:
                            r -= 1
                        if r < 0:
                            r = 0
                    v = -search(q, r, -alpha - 1, -alpha, ply1, Fq, Fp)
                    if v > alpha and (v < beta or r != nd):
                        v = -search(q, nd, -beta, -alpha, ply1, Fq, Fp)
                pos[p] = a
            else:
                w = mv - 100
                sN = oN
                sS = oS
                sE = oE
                sW = oW
                sb = blocked
                sz = wz
                aN, aS, aE, aW = WA_[w]
                oN &= aN
                oS &= aS
                oE &= aE
                oW &= aW
                blocked |= WCF_[w]
                wz ^= ZW_[w]
                sm = wm[0]
                wm[0] = sm | (1 << w)
                tog = WTG_[w]
                for x, bit in tog:
                    o = opn[x] ^ bit
                    opn[x] = o
                    adj[x] = NT_[x][o]
                wl[p] = wp - 1
                Fq2 = child_field(Fq, w, q)
                Fp2 = child_field(Fp, w, p) if np_ == dp else field(p)
                if i == 0:
                    v = -search(q, nd, -beta, -alpha, ply1, Fq2, Fp2)
                else:
                    r = nd
                    if depth >= 3 and (i >= 3 or s < 3000):
                        r -= 1
                        if i >= 8 and depth >= 4 and s < 3000:
                            r -= 1
                    if PLMR_ and depth >= PLD_ and gap >= PG1_:
                        r -= 1
                        if gap >= PG2_ and depth > PLD_:
                            r -= 1
                    if r < 0:
                        r = 0
                    v = -search(q, r, -alpha - 1, -alpha, ply1, Fq2, Fp2)
                    if v > alpha and (v < beta or r != nd):
                        v = -search(q, nd, -beta, -alpha, ply1, Fq2, Fp2)
                wl[p] = wp
                for x, bit in tog:
                    o = opn[x] ^ bit
                    opn[x] = o
                    adj[x] = NT_[x][o]
                oN = sN
                oS = sS
                oE = sE
                oW = sW
                blocked = sb
                wz = sz
                wm[0] = sm
            i += 1
            if v > best:
                best = v
                bm = mv
                if v > alpha:
                    alpha = v
                    if v >= beta:
                        if mv != k0:
                            kl[1] = k0
                            kl[0] = mv
                        if mv >= 100:
                            h = hist[mv - 100] + depth * depth * 8
                            hist[mv - 100] = h if h < 6000 else 6000
                        break
        onpath.discard(key)
        TT[key] = (depth, 1 if best >= beta else (2 if best <= alpha0 else 0), best, bm)
        return best

    def place(w):
        nonlocal oN, oS, oE, oW, blocked, wz
        saved = (oN, oS, oE, oW, blocked, wz)
        aN, aS, aE, aW = WALL_AND[w]
        oN &= aN
        oS &= aS
        oE &= aE
        oW &= aW
        blocked |= WALL_CONF[w]
        wz ^= ZW[w]
        wm[0] |= 1 << w
        for x, bit in WALL_TOG[w]:
            opn[x] ^= bit
            adj[x] = NT[x][opn[x]]
        return saved

    def unplace(w, saved):
        nonlocal oN, oS, oE, oW, blocked, wz
        for x, bit in WALL_TOG[w]:
            opn[x] ^= bit
            adj[x] = NT[x][opn[x]]
        oN, oS, oE, oW, blocked, wz = saved
        wm[0] &= ~(1 << w)

    def root_child(mv, depth, alpha, beta, F0, F1):
        """Value for us of root move mv searched to `depth` plies below it."""
        if mv < 100:
            a = pos[0]
            pos[0] = mv
            tax = revisit.get(mv, 0) if revisit else 0
            try:
                # applied to decided scores too: when every move "loses" (or
                # "wins"), walking somewhere new beats shuffling to move 500
                return -search(1, depth, -beta - tax, -alpha - tax, 1, F1, F0) - tax
            finally:
                pos[0] = a
        w = mv - 100
        saved = place(w)
        wl[0] -= 1
        try:
            return -search(1, depth, -beta, -alpha, 1, field(1), field(0))
        finally:
            wl[0] += 1
            unplace(w, saved)

    try:
        # ------------------------------------------------------------- root
        F0 = field(0)
        F1 = field(1)
        a0 = pos[0]
        b0 = pos[1]
        dp = F0[a0]
        dq = F1[b0]
        scored = []
        for y in root_pawn:
            d = F0[y]
            if d == 0:
                return y
            if d < 0:
                d = 99
            scored.append(((dp - d) * 10000, y))
        if wl[0] > 0 and legal_wall_set:
            for g, w, nq, np_ in gen_walls(0, F0, F1, a0, b0, dp, dq, -1):
                if w in legal_wall_set:
                    scored.append((g * 10000 - 7000, 100 + w))
        if ROOT_DEFENSE and wl[0] > 0 and wl[1] > 0 and legal_wall_set:
            # Defensive walls: ones that take away the opponent's best cut against
            # us.  Found with a 2-ply probe, then verified by the real search.
            kq = wz ^ ZP0[a0] ^ ZP1[b0] ^ ZSIDE
            threat = 0
            for g, w, nq, np_ in gen_walls(1, F1, F0, b0, a0, dq, dp, kq ^ ZN[wl[0]]):
                if g > threat:
                    threat = g
            if threat >= 2:
                have = set(mv for _, mv in scored)
                cand = []
                stop_at = deadline - 0.85 * TIME_BUDGET
                for w in legal_wall_set:
                    if 100 + w in have:
                        continue
                    if _perf() > stop_at:
                        break
                    saved = place(w)
                    Fa = child_field(F0, w, 0)
                    Fb = child_field(F1, w, 1)
                    da = Fa[a0]
                    db = Fb[b0]
                    if da >= 0 and db >= 0:
                        left = 0
                        for g, w2, nq, np_ in gen_walls(1, Fb, Fa, b0, a0, db, da,
                                                        wz ^ kq ^ saved[5] ^ ZN[wl[0] - 1]):
                            if g > left:
                                left = g
                        ben = threat - left + (db - dq) - (da - dp)
                        if ben >= 2:
                            cand.append((ben, w))
                    unplace(w, saved)
                cand.sort(reverse=True)
                for ben, w in cand[:ROOT_DEFENSE]:
                    scored.append((ben * 10000 - 14000, 100 + w))
        if not scored:
            return -1
        scored.sort(reverse=True)
        if POL_ and POLICY_ROOT and len(scored) > 2:
            gen0 = {w: (g, nq, np_) for g, w, nq, np_ in gen_walls(0, F0, F1, a0, b0, dp, dq, -1)}
            cands = []
            for s, mv in scored:
                if mv < 100:
                    d = F0[mv]
                    cands.append((mv, dp - (d if d >= 0 else dp + 3), dq, d, 0))
                elif (mv - 100) in gen0:
                    g, nq, np_ = gen0[mv - 100]
                    cands.append((mv, g, nq, np_, 0))
                else:
                    cands.append((mv, 0, dq, dp, 1))
            lg = plogits(0, a0, b0, wl[0], wl[1], dp, dq, cands, True)
            scored = sorted(zip(lg, [mv for _, mv in scored]), reverse=True)
            STATS["root_policy"] = [(round(v, 2), mv) for v, mv in scored]
        order = [mv for _, mv in scored]
        best = order[0]
        STATS.update(depth=0, nodes=0, value=None, moves=len(order))
        if len(order) == 1:
            return best

        onpath.add(wz ^ ZP0[pos[0]] ^ ZP1[pos[1]] ^ ZN[wl[0]])
        prev = None
        cap = _T0[0] + HARD_CAP if _T0[0] else deadline + 1.0
        hard = min(deadline - TIME_BUDGET + TIME_MAX, cap)
        deadline = min(deadline, cap)
        prev_best = None
        depth = 1
        hold = 0
        pgate = PASS_ROOT and _PASS_OK[0] and wl[0] == 0 and wl[1] > 0 and dq - dp >= PASS_LEAD
        try:
            for depth in range(1, MAX_DEPTH):
                if prev is not None and depth >= 3:
                    alpha = prev - 35
                    beta = prev + 35
                else:
                    alpha = -INF
                    beta = INF
                while True:
                    a_ = alpha
                    bv = -INF
                    bmv = None
                    i = 0
                    for mv in order:
                        if i == 0:
                            v = root_child(mv, depth, a_, beta, F0, F1)
                        else:
                            v = root_child(mv, depth, a_, a_ + 1, F0, F1)
                            if v > a_ and v < beta:
                                try:
                                    v = root_child(mv, depth, a_, beta, F0, F1)
                                except _Timeout:
                                    best = mv     # beat the best move on the null window
                                    raise
                        i += 1
                        if v > bv:
                            bv = v
                            bmv = mv
                            if v > a_:
                                a_ = v
                                best = mv
                                if v >= beta:
                                    break
                    if bv <= alpha:
                        if EXT_ON and depth >= EXT_DEPTH and deadline < hard:
                            deadline = hard
                        alpha = -INF
                        continue
                    if bv >= beta:
                        beta = INF
                        order.remove(bmv)
                        order.insert(0, bmv)
                        continue
                    break
                best = bmv
                if EXT_ON and EXT_CHANGE and depth >= EXT_DEPTH and prev_best is not None and bmv != prev_best and deadline < hard:
                    deadline = hard
                prev_best = bmv
                order.remove(bmv)
                order.insert(0, bmv)
                prev = bv
                STATS.update(depth=depth + 1, nodes=nodes, value=bv)
                hold = 0
                if pgate and depth >= PASS_DEPTH and 1000 - RACE < bv <= 0:
                    # No real move is better than a draw although we lead the race (plug-threat /
                    # repetition plateau).  (1) zugzwang: is the opponent lost when IT must move?
                    if -search(1, depth, 1000 - RACE, 1001 - RACE, 1, F1, F0) >= RACE - 1000:
                        best = -2
                        STATS["pass"] = depth
                        break
                    # (2) hold: the best move is a 0-valued pawn step that does not bring us closer
                    # (REVISIT_TAX would walk us away from the goal until the race is lost);
                    # standing still keeps the lead when the pass is worth no less.
                    if bv == 0 and bmv < 100 and F0[bmv] >= dp:
                        if -search(1, depth, 0, 1, 1, F1, F0) >= 0:
                            hold = 1
                if bv >= WIN - 500 or (bv <= -WIN + 500 and not BOOK_):
                    break           # USE_BOOK: keep searching when lost (REVISIT_TAX acts)
        except _Timeout:
            pass
        if hold and best == prev_best:
            best = -2
            STATS["pass"] = 0
        STATS["nodes"] = nodes
        return best
    finally:
        # the recursive closure is a reference cycle that would keep TT, GEN,
        # ... alive until a full garbage collection; cut it so they die here
        search = root_child = gen_walls = exact = None


# -------------------------------------------------------------- lock guard
# The path rule ignores pawns, so an opponent may wall the board until the
# only way to our goal runs through the square its own pawn is standing on
# and then never move again (a draw).  Each turn we let the opponent place
# walls alone, greedily, and see whether it can reach such a lock.  If it
# is within LOCK_TRIG walls of one and we cannot simply get there first, we
# play the cheapest wall of our own after which no lock is reachable any
# more (typically a wall that overlaps or crosses one of the walls it still
# needs, which the path rule then forbids for good).
LOCK_TRIG = 2
LOCK_TIME = 0.18        # seconds the guard may use on a turn where it triggers


def _lg_flood(x, goalmask, m, block):
    m0, m1, m2, m3 = m
    keep = FULL ^ block
    goalmask &= keep
    v = 1 << x
    d = 0
    while not (v & goalmask):
        nv = (v | ((v & m0) >> 9) | ((v & m1) << 9) | ((v & m2) << 1) | ((v & m3) >> 1)) & keep
        if nv == v:
            return -1
        v = nv
        d += 1
    return d


def _lg_breach(a, b, goal_row, m):
    '''Moves we need to reach goal_row if the opponent pawn never leaves b.'''
    m0, m1, m2, m3 = m

    def nb(x):
        r = []
        if (m0 >> x) & 1:
            r.append(x - 9)
        if (m1 >> x) & 1:
            r.append(x + 9)
        if (m2 >> x) & 1:
            r.append(x + 1)
        if (m3 >> x) & 1:
            r.append(x - 1)
        return r

    seen = {a}
    frontier = [a]
    k = 0
    while frontier:
        k += 1
        nxt = []
        for x in frontier:
            for y in nb(x):
                if y != b:
                    ys = (y,)
                else:
                    nbb = nb(b)
                    j = b + b - x
                    ys = (j,) if j in nbb else [z for z in nbb if z != x]
                for z in ys:
                    if z // 9 == goal_row:
                        return k
                    if z not in seen:
                        seen.add(z)
                        nxt.append(z)
        frontier = nxt
    return 99


def _lg_key(a, b, my_goal, op_goal, m):
    '''None if the walls are illegal, else (locked, how hard b is to avoid, distance).'''
    gm = 0x1FF << (9 * my_goal)
    d = _lg_flood(a, gm, m, 0)
    if d < 0 or _lg_flood(b, 0x1FF << (9 * op_goal), m, 0) < 0:
        return None
    db = _lg_flood(a, gm, m, 1 << b)
    if db >= 0:
        return (0, db, d)
    br = _lg_breach(a, b, my_goal, m)
    if br >= 99:
        return (1, 999, d)
    return (0, 200 + br, d)


def _lg_sim(a, b, my_goal, op_goal, m, blocked, nwalls, cands, t_stop):
    '''Can the opponent, placing up to nwalls walls in a row, lock us out?
    Returns (walls needed or 0, the walls); (-1, ...) if out of time.'''
    cur = _lg_key(a, b, my_goal, op_goal, m)
    if cur is None:
        return 0, []
    plan = []
    for step in range(min(nwalls, 9)):
        best = None
        if _perf() > t_stop:
            return -1, plan
        for w in cands:
            if (blocked >> w) & 1:
                continue
            if not (w & 15) and _perf() > t_stop:
                return -1, plan
            aN, aS, aE, aW = WALL_AND[w]
            m2 = (m[0] & aN, m[1] & aS, m[2] & aE, m[3] & aW)
            k = _lg_key(a, b, my_goal, op_goal, m2)
            if k is not None and k > cur and (best is None or k > best[0]):
                best = (k, w, m2)
        if best is None:
            return 0, plan
        cur, w, m = best
        blocked |= WALL_CONF[w]
        plan.append(w)
        if cur[0]:
            return len(plan), plan
    return 0, plan


def _lock_guard(a, b, my_goal, op_goal, placed, legal, my_wl, op_wl, t_stop):
    if my_wl <= 0 or op_wl <= 0 or not legal:
        return None
    m = [INIT_N, INIT_S, INIT_E, INIT_W]
    blocked = 0
    for w in placed:
        aN, aS, aE, aW = WALL_AND[w]
        m[0] &= aN
        m[1] &= aS
        m[2] &= aE
        m[3] &= aW
        blocked |= WALL_CONF[w]
    m = tuple(m)
    k0 = _lg_key(a, b, my_goal, op_goal, m)
    if k0 is None or k0[0]:
        return None
    every = range(128)
    n, plan = _lg_sim(a, b, my_goal, op_goal, m, blocked, op_wl, every, t_stop)
    if n <= 0 or n > LOCK_TRIG:
        return None
    if _lg_breach(a, b, my_goal, m) <= n:
        return None                         # we simply get there first
    br, bc = divmod(b, 9)
    near = [w for w in every
            if (abs(((w & 63) >> 3) - br) <= 2 and abs((w & 7) - bc) <= 3)
            or (w < 64 and abs(((w & 63) >> 3) - br) <= 1)]
    conf = 0
    for w in plan:
        conf |= WALL_CONF[w]
    cands = []
    for w in legal:
        if not ((conf >> w) & 1) and w not in near:
            continue
        aN, aS, aE, aW = WALL_AND[w]
        m2 = (m[0] & aN, m[1] & aS, m[2] & aE, m[3] & aW)
        k = _lg_key(a, b, my_goal, op_goal, m2)
        if k is None or k[0] or k[2] > k0[2] + 3:
            continue
        cands.append((k[2], 0 if (conf >> w) & 1 else 1, w, m2))
    cands.sort()
    fallback = None
    for d2, _, w, m2 in cands:
        if _perf() > t_stop:
            break
        b2 = blocked | WALL_CONF[w]
        n2, _p = _lg_sim(a, b, my_goal, op_goal, m2, b2, op_wl, near, t_stop)
        if not n2:
            n2, _p = _lg_sim(a, b, my_goal, op_goal, m2, b2, op_wl, every, t_stop)
            if not n2:
                return w
        if n2 < 0:
            break
        if n2 > n and (fallback is None or n2 > fallback[0]):
            fallback = (n2, w)
    return fallback[1] if fallback else None

# ------------------------------------------------------------- opening book
# "seat my_cell opp_cell my_walls_left walls=action".  seat 0 starts on row 8.
# Cells are row,col digits; walls are sorted tokens H/V + anchor row,col.
# An entry also answers the left-right mirror image of its position.
#
# What the entries say (each was played out against the local pool from the
# standard start at 0.1 s, 0.2 s and default budgets before it was kept):
#   seat 0 (moves first): run the centre file to row 5.  With the pawns two
#     apart and us to move, whoever steps forward gets jumped and a sidestep
#     loses a tempo, so spend a wall as the tempo move: H(5,4) behind our
#     own pawn, on the opponent's path.  (Stepping in scored as well at full
#     speed but clearly worse at lower search depth.)
#   seat 1: run the centre file to row 3; the opponent then has that problem.
#     If it walls first, answer with the vertical wall that crosses the
#     anchor its wall line needs next (V(5,2) against H(5,4)): the door next
#     to its wall then stays open for good.  If it sidesteps, walk on.  If it
#     steps in, jump, keep running, and pin the door the same way when it
#     walls in front of us.  Against a wall on our goal line go round at once.
