BOOK = dict(e.split("=") for e in _BOOK_TEXT.split())


def _book_key(seat, mp, op, my_wl, toks):
    return "%d%d%d%d%d%s%s" % (seat, mp[0], mp[1], op[0], op[1], "abcdefghijk"[my_wl], "".join(sorted(toks)))


def _mirror_tok(t):
    return "%s%s%d" % (t[0], t[1], (8 if t[0] == "m" else 7) - int(t[2]))


def _book_action(my_goal, mp, op, placed, my_wl, legal_moves, legal_walls):
    if not BOOK or len(placed) > 20 or not 0 <= my_wl <= 10:
        return None
    seat = 0 if my_goal == 0 else 1
    toks = ["%s%d%d" % ("V" if w >= 64 else "H", (w & 63) >> 3, w & 7) for w in placed]
    t = BOOK.get(_book_key(seat, mp, op, my_wl, toks))
    if t is None:
        t = BOOK.get(_book_key(seat, [mp[0], 8 - mp[1]], [op[0], 8 - op[1]], my_wl,
                               [_mirror_tok(x) for x in toks]))
        if t is None:
            return None
        t = _mirror_tok(t)
    r = int(t[1])
    c = int(t[2])
    if t[0] == "m":
        if [r, c] in legal_moves:
            return {"type": "move", "to": [r, c]}
        return None
    if ((64 if t[0] == "V" else 0) + r * 8 + c) in legal_walls:
        return {"type": "wall", "orientation": t[0], "row": r, "col": c}
    return None


# ------------------------------------------------------- observation parsing
def _is_cell(v):
    return (isinstance(v, (list, tuple)) and len(v) == 2
            and all(isinstance(t, int) and not isinstance(t, bool) for t in v))


def _player_pos(pl):
    for k in ("position", "pos", "cell", "location", "at"):
        if _is_cell(pl.get(k)):
            return pl[k]
    if isinstance(pl.get("row"), int) and isinstance(pl.get("col"), int):
        return [pl["row"], pl["col"]]
    for v in pl.values():
        if _is_cell(v):
            return v
    raise KeyError("pawn position not found")


def _player_walls(pl, default):
    for k in ("walls_left", "walls_remaining", "remaining_walls", "walls",
              "wall_count", "num_walls"):
        v = pl.get(k)
        if isinstance(v, int) and not isinstance(v, bool):
            return v
    for k, v in pl.items():
        if "wall" in str(k).lower() and isinstance(v, int) and not isinstance(v, bool):
            return v
    return default


def _wall_index(item):
    """Wall given as a dict or as a sequence like ['H', r, c] -> index."""
    if isinstance(item, dict):
        o = item.get("orientation", item.get("o", item.get("dir")))
        r = item.get("row", item.get("r"))
        c = item.get("col", item.get("c"))
    else:
        o = next((t for t in item if isinstance(t, str)), None)
        nums = [t for t in item if isinstance(t, int) and not isinstance(t, bool)]
        r, c = nums[0], nums[1]
    o = str(o).upper()[:1]
    if o not in ("H", "V") or not (0 <= r < 8 and 0 <= c < 8):
        raise ValueError("bad wall")
    return (64 if o == "V" else 0) + r * 8 + c


def _placed_walls(obs):
    src = obs.get("walls")
    if src is None:
        for k, v in obs.items():
            lk = str(k).lower()
            if "wall" in lk and "legal" not in lk and isinstance(v, (list, tuple, dict)):
                src = v
                break
    out = []
    if isinstance(src, dict):          # e.g. {"H": [[r, c], ...], "V": [...]}
        for o, items in src.items():
            for it in items:
                try:
                    out.append(_wall_index([str(o), it[0], it[1]]))
                except Exception:
                    pass
    elif src:
        for it in src:
            try:
                out.append(_wall_index(it))
            except Exception:
                pass
    return out


def _fallback(obs):
    """Greedy step along the arena's own distance matrix; never raises."""
    try:
        moves = obs.get("legal_moves") or []
        if moves:
            dist = obs.get("distances")

            def key(m):
                try:
                    d = dist[m[0]][m[1]]
                    return d if d >= 0 else 10 ** 6
                except Exception:
                    return 10 ** 6
            m = min(moves, key=key)
            return {"type": "move", "to": [int(m[0]), int(m[1])]}
    except Exception:
        pass
    return {"type": "pass"}



# ------------------------------------------------- red-team: exact pure race
# Both sides out of walls: the game is a two-pawn game on a fixed graph
# (<= 2 x 81 x 81 states).  Retrograde analysis with the legal pass gives the
# exact value; the walls cannot change any more, so one table serves the
# rest of the game.  (rl/endgame/race.py retrograde, me = side 0.)
_RT_TAB = {}


def _rt_moves(adj, a, b):
    out = []
    for y in adj[a]:
        if y != b:
            out.append(y)
        else:
            j = b + b - a
            if j in adj[b]:
                out.append(j)
            else:
                for z in adj[b]:
                    if z != a:
                        out.append(z)
    return out


def _rt_table(adj, F):
    W_ = 100000
    goal = (set(x for x in range(81) if F[0][x] == 0), set(x for x in range(81) if F[1][x] == 0))
    succ = {}
    val = {}
    frontier = []
    for p0 in range(81):
        if p0 in goal[0]:
            continue
        for p1 in range(81):
            if p1 == p0 or p1 in goal[1]:
                continue
            m0 = _rt_moves(adj, p0, p1)
            m1 = _rt_moves(adj, p1, p0)
            s = (p0, p1, 0)
            succ[s] = [(y, p1, 1) for y in m0] + [(p0, p1, 1)]
            for y in m0:
                if y in goal[0]:
                    val[s] = W_ - 1
                    frontier.append(s)
                    break
            s = (p0, p1, 1)
            succ[s] = [(p0, y, 0) for y in m1] + [(p0, p1, 0)]
            for y in m1:
                if y in goal[1]:
                    val[s] = W_ - 1
                    frontier.append(s)
                    break
    pred = {}
    for s, lst in succ.items():
        for t in lst:
            pred.setdefault(t, []).append(s)
    cnt = dict((s, len(lst)) for s, lst in succ.items())
    while frontier:
        nxt = []
        for s in frontier:
            v = val[s]
            if v > 0:
                for t in pred.get(s, ()):
                    if t in val:
                        continue
                    cnt[t] -= 1
                    if cnt[t] == 0:
                        worst = min(val[u] for u in succ[t] if u in val)
                        val[t] = -(worst - 1)
                        nxt.append(t)
            else:
                for t in pred.get(s, ()):
                    if t in val:
                        continue
                    val[t] = W_ - ((W_ + v) + 1)
                    nxt.append(t)
        frontier = nxt
    return val


def _rt_race(mp, op, my_goal, op_goal, placed, legal_moves):
    """Exact action in a wall-less race, or None.  Win fastest, lose slowest; in a draw keep
    the draw, step forward when that keeps it, otherwise pass (the opponent has to commit)."""
    key = (my_goal, tuple(sorted(placed)))
    T = _RT_TAB.get(key)
    if T is None:
        opn = list(INIT_OPEN)
        for w in placed:
            for x, bit in WALL_TOG[w]:
                if opn[x] & bit:
                    opn[x] ^= bit
        adj = [NT[x][opn[x]] for x in range(81)]
        F = (_bfs(adj, my_goal), _bfs(adj, op_goal))
        _RT_TAB.clear()
        T = _RT_TAB[key] = (_rt_table(adj, F), F)
    val, F = T
    a = mp[0] * 9 + mp[1]
    b = op[0] * 9 + op[1]
    best = None
    for m in legal_moves:
        y = m[0] * 9 + m[1]
        if y == b:
            continue
        v = val.get((y, b, 1), 0)       # unresolved states are draws
        k = (-v, -F[0][y], 1)
        if best is None or k > best[0]:
            best = (k, m)
    k = (-val.get((a, b, 1), 0), -F[0][a], 0)
    if best is None or k > best[0]:
        return {"type": "pass"}
    return {"type": "move", "to": [int(best[1][0]), int(best[1][1])]}


# ------------------------------------------------------------- plug pass
# The path rule ignores pawns and a pawn is never forced to move.  If the
# opponent cannot reach its goal row while our pawn stays where it is (its
# jumps over us included), passing every turn is a guaranteed draw: walls
# only close edges.  The search has no pass move, so without this rule it
# steps off the plug and loses positions it scored as drawn (USE_PLUGT).
USE_PLUG_PASS = 1
PLUG_PASS_MAX = 0        # pass when the root value is <= this (10 = one step)


def _plug_hold(me, op, my_goal, op_goal, placed):
    """(held, behind): the pawn on op cannot reach row op_goal while ours stays on me;
    behind = our shortest path is longer than the opponent's."""
    opn = list(INIT_OPEN)
    for w in placed:
        for x, bit in WALL_TOG[w]:
            if opn[x] & bit:
                opn[x] ^= bit
    adj = [NT[x][opn[x]] for x in range(81)]
    seen = [False] * 81
    seen[op] = True
    stack = [op]
    while stack:
        c = stack.pop()
        if c // 9 == op_goal:
            return False, False
        for n in adj[c]:
            if n != me:
                outs = (n,)
            else:
                j = n + n - c
                nb = adj[n]
                outs = (j,) if j in nb else [z for z in nb if z != c]
            for y in outs:
                if not seen[y]:
                    seen[y] = True
                    stack.append(y)
    dm = _bfs(adj, my_goal)[me]
    do = _bfs(adj, op_goal)[op]
    return True, dm > do


_OPTRACK = {}


def _op_gate(obs, op, op_goal, nwalls):
    """Count consecutive opponent turns without a pawn move (module state, one game per process
    or module instance; reset when the turn counter or the wall count goes back)."""
    turn = int(obs.get("turn", 0) or 0)
    t = _OPTRACK
    if not t or turn < t.get("turn", -1) or nwalls < t.get("walls", 0) or turn < 2:
        t.clear()
        t.update(turn=turn, walls=nwalls, pos=tuple(op), still=0)
        return 0, abs(op[0] - (8 - op_goal))
    if tuple(op) == t["pos"]:
        t["still"] += 1
    else:
        t["still"] = 0
    t.update(turn=turn, walls=nwalls, pos=tuple(op))
    return t["still"], abs(op[0] - (8 - op_goal))


GATE_TILINGS = ((1, 3, 5, 7), (0, 3, 5, 7), (0, 2, 5, 7), (0, 2, 4, 7), (0, 2, 4, 6))
POISON_MAX = 4
CAMP = {'seen': None, 'prev': None, 'streak': 0, 'passed': False, 'opp_h': set(), 'active': False, 'stop': False, 'placed': 0}

# Reset the anti-camping state at the start of a game.
def _camp_reset():
    CAMP['seen'] = None
    CAMP['prev'] = None
    CAMP['streak'] = 0
    CAMP['passed'] = False
    CAMP['opp_h'] = set()
    CAMP['active'] = False
    CAMP['stop'] = False
    CAMP['placed'] = 0

# Remember our own wall so it is not counted as an opponent wall.
def _camp_note(action):
    seen = CAMP['seen']
    if seen is not None and action.get('type') == 'wall':
        CAMP['seen'] = seen | {(action['orientation'], action['row'], action['col'])}

# Gate tilings the opponent can still complete with legal horizontal walls.
def _camp_live(placed, walls_v, legal_h):
    live = []
    for t in GATE_TILINGS:
        ts = set(t)
        if not placed <= ts:
            continue
        need = ts - placed
        if need & walls_v or not need <= legal_h:
            continue
        live.append(ts)
    return live

# Vertical wall slot that breaks the most live tilings (prefer central slots).
def _camp_pick(live, placed, legal_v):
    best = None
    for a in range(8):
        if a in placed or a not in legal_v:
            continue
        kill = 0
        for ts in live:
            if a in ts:
                kill += 1
        if not kill:
            continue
        key = (-kill, min(a, 7 - a), a)
        if best is None or key < best[0]:
            best = (key, a)
    return None if best is None else best[1]

# Anti-camping driver: detects the camping pattern and returns a wall code, or None.
def _camp_poison(obs):
    G = obs['you']['goal_row']
    B = G if G == 0 else G - 1
    hs = set(((r, c) for r, c in obs['walls']['horizontal']))
    vs = set(((r, c) for r, c in obs['walls']['vertical']))
    orow, ocol = obs['opponent']['position']
    owalls = obs['opponent']['walls_remaining']
    cur = frozenset([('H', r, c) for r, c in hs] + [('V', r, c) for r, c in vs])
    seen = CAMP['seen']
    new = cur if seen is None else cur - seen
    CAMP['seen'] = cur
    prev = CAMP['prev']
    if prev is not None and (orow, ocol, owalls) == prev:
        CAMP['passed'] = True
    CAMP['prev'] = (orow, ocol, owalls)
    if orow != G:
        CAMP['streak'] = 0
        if CAMP['active'] and abs(orow - G) >= 2:
            CAMP['active'] = False
            CAMP['stop'] = True
        if not CAMP['active']:
            return None
    else:
        CAMP['streak'] += 1
    if CAMP['stop']:
        return None
    for kind, r, c in new:
        if kind == 'H' and r == B:
            CAMP['opp_h'].add(c)
    opp_h = len(CAMP['opp_h'])
    if not CAMP['active']:
        if obs.get('turn', 0) < 2 or not (opp_h >= 2 or (opp_h >= 1 and (CAMP['passed'] or CAMP['streak'] >= 3)) or (CAMP['passed'] and CAMP['streak'] >= 3)):
            return None
        CAMP['active'] = True
    if CAMP['placed'] >= POISON_MAX or obs['you']['walls_remaining'] <= 0 or owalls <= 0:
        CAMP['active'] = False
        CAMP['stop'] = True
        return None
    placed = set((c for r, c in hs if r == B))
    walls_v = set((c for r, c in vs if r == B))
    legal_h = set((w['col'] for w in obs['legal_walls'] if w['orientation'] == 'H' and w['row'] == B))
    legal_v = set((w['col'] for w in obs['legal_walls'] if w['orientation'] == 'V' and w['row'] == B))
    live = _camp_live(placed, walls_v, legal_h)
    if not live:
        CAMP['active'] = False
        return None
    a = _camp_pick(live, placed, legal_v)
    if a is None:
        return None
    CAMP['placed'] += 1
    return 64 + B * 8 + a


def _choose(obs, t0):
    _T0[0] = t0
    you = obs["you"]
    opp = obs["opponent"]
    my_goal = int(you["goal_row"])
    op_goal = int(opp.get("goal_row", 8 - my_goal))
    mp = _player_pos(you)
    op = _player_pos(opp)
    placed = []
    seen = set()
    for w in _placed_walls(obs):
        if w not in seen:
            seen.add(w)
            placed.append(w)
    legal_walls = {}
    for it in obs.get("legal_walls") or []:
        try:
            legal_walls[_wall_index(it)] = it
        except Exception:
            pass
    my_wl = _player_walls(you, 10 if legal_walls else 0)
    op_wl = _player_walls(opp, max(0, 20 - len(placed) - my_wl))
    if not legal_walls:
        my_wl = 0
    my_wl = max(0, min(31, my_wl))
    op_wl = max(0, min(31, op_wl))

    legal_moves = [[int(m[0]), int(m[1])] for m in (obs.get("legal_moves") or [])]
    pawn = [m[0] * 9 + m[1] for m in legal_moves]
    for m in legal_moves:
        if m[0] == my_goal:
            return {"type": "move", "to": m}

    if RACE_ROOT and my_wl == 0 and op_wl == 0 and legal_moves:
        try:
            act = _rt_race(mp, op, my_goal, op_goal, placed, legal_moves)
        except Exception:
            act = None
        if act is not None:
            STATS.update(depth=0, nodes=0, value="race-exact")
            return act

    turn_ = int(obs.get("turn", 99) or 0)
    if turn_ < 2:
        _PASS.clear()
        _camp_reset()
    pk_ = (tuple(mp), tuple(op), tuple(sorted(placed)))
    if _PASS.get("k") == pk_:
        _PASS["off"] = 1            # our pass was answered by a pass: never pass again this game
    _PASS["k"] = None
    _PASS_OK[0] = 0 if (_PASS.get("off") or _PASS.get("n", 0) >= PASS_MAX or turn_ >= 400) else 1

    revisit = None
    if USE_BOOK:
        try:
            act = _book_action(my_goal, mp, op, placed, my_wl, legal_moves, legal_walls)
        except Exception:
            act = None
        if act is not None:
            STATS.update(depth=0, nodes=0, value="book")
            return act

    if USE_REVISIT:
        # anti-shuffle bookkeeping: cells we stood on under the current wall layout
        wk = tuple(sorted(placed))
        if _VISITS.get("walls") != wk or int(obs.get("turn", 99)) < 2:
            _VISITS.clear()
            _VISITS["walls"] = wk
        here = mp[0] * 9 + mp[1]
        _VISITS[here] = _VISITS.get(here, 0) + 1
        revisit = dict((c, REVISIT_TAX * min(n, 20)) for c, n in _VISITS.items()
                       if c != "walls" and c != here)

    if USE_CAMP:
        try:
            cw = _camp_poison(obs)
        except Exception:
            cw = None
        if cw is not None and cw in legal_walls:
            _w = {"type": "wall", "orientation": "V", "row": (cw & 63) >> 3, "col": cw & 7}
            _camp_note(_w)
            STATS.update(depth=0, nodes=0, value="camp-guard")
            return _w

    gate_ok = True
    if USE_LOCK_GUARD:
        try:
            still, home = _op_gate(obs, op, op_goal, len(placed))
            gate_ok = still >= LG_GATE_STILL and home <= LG_GATE_HOME
        except Exception:
            gate_ok = True
    if USE_LOCK_GUARD and gate_ok:
        try:
            w = _lock_guard(mp[0] * 9 + mp[1], op[0] * 9 + op[1], my_goal, op_goal, placed,
                            legal_walls, my_wl, op_wl, t0 + min(LOCK_TIME, 0.5 * TIME_BUDGET))
        except Exception:
            w = None
        if w is not None and w in legal_walls:
            STATS.update(depth=0, nodes=0, value="lock-guard")
            return {"type": "wall", "orientation": "V" if w >= 64 else "H",
                    "row": (w & 63) >> 3, "col": w & 7}

    held = behind = False
    if USE_PLUG_PASS:
        try:
            held, behind = _plug_hold(mp[0] * 9 + mp[1], op[0] * 9 + op[1], my_goal, op_goal, placed)
        except Exception:
            held = False
        if held:
            STATS["value"] = None       # never read a stale value below
    best = _search((mp[0] * 9 + mp[1], op[0] * 9 + op[1]), (my_goal, op_goal),
                   (my_wl, op_wl), placed, pawn, set(legal_walls),
                   (_perf() if GUARD_OWN_CLOCK else t0) + TIME_BUDGET, revisit)
    if held:
        v = STATS.get("value")
        if (v is None and behind) or (isinstance(v, (int, float)) and v <= PLUG_PASS_MAX):
            STATS["plug_pass"] = v
            return {"type": "pass"}
    if best == -2:
        _PASS["k"] = pk_
        _PASS["n"] = _PASS.get("n", 0) + 1
        return {"type": "pass"}
    if best >= 100:
        w = best - 100
        if w in legal_walls:
            return {"type": "wall", "orientation": "V" if w >= 64 else "H",
                    "row": (w & 63) >> 3, "col": w & 7}
    elif best >= 0:
        m = [best // 9, best % 9]
        if m in legal_moves:
            return {"type": "move", "to": m}
    return _fallback(obs)


def choose_action(observation):
    t0 = _perf()
    gc_on = gc.isenabled()
    if gc_on:
        gc.disable()            # no collector pauses while our clock runs
    try:
        return _choose(observation, t0)
    except Exception:
        return _fallback(observation)
    finally:
        if gc_on:
            gc.enable()


# =====================================================================
# delta layer: tunable parameters, camp guard switch, book hook
# =====================================================================
import json as _json
import math as _math
import os as _os

USE_CAMP = 1            # 009's anti-camping guard (see _camp_poison)
W_CAP, W_D0, W_TAU, W_MAXV = 29.078, 6.73, 9.426, 18   # wall-in-hand value curve (units: 10 = one step)
_TUNABLE = (
    "TIME_BUDGET", "TIME_MAX", "HARD_CAP", "EXT_ON", "EXT_DEPTH", "EXT_CHANGE",
    "TEXEL_TEMPO", "STEP_VALUE", "POLICY_GAP1", "POLICY_GAP2", "REVISIT_TAX",
    "PASS_ROOT", "PASS_LEAD", "PASS_DEPTH", "PASS_MAX", "PLUG_PASS_MAX",
    "LG_GATE_STILL", "LG_GATE_HOME", "LOCK_TIME", "USE_CAMP", "USE_BOOK",
    "USE_LOCK_GUARD", "USE_REVISIT", "USE_PLUG_PASS", "USE_TEXEL", "USE_POLICY",
    "W_CAP", "W_D0", "W_TAU", "W_MAXV", "POISON_MAX",
)


def wall_curve(cap=None, d0=None, tau=None, maxv=None, n=None):
    """WALL_BY_DIST[ds + dt]: value of one wall in hand (reproduces the shipped list)."""
    cap = W_CAP if cap is None else cap
    d0 = W_D0 if d0 is None else d0
    tau = W_TAU if tau is None else tau
    maxv = W_MAXV if maxv is None else maxv
    n = len(WALL_BY_DIST) if n is None else n
    out = []
    for d in range(n):
        x = d - d0
        out.append(0 if x < 1 else int(min(maxv, round(cap * (1 - _math.exp(-x / tau))))))
    return out


def set_params(params):
    """Override module globals (only names in _TUNABLE); rebuilds the wall curve."""
    global WALL_BY_DIST
    g = globals()
    rebuild = False
    for k, v in (params or {}).items():
        if k not in _TUNABLE:
            continue
        g[k] = v
        rebuild = rebuild or k in ("W_CAP", "W_D0", "W_TAU", "W_MAXV")
    if rebuild:
        WALL_BY_DIST = wall_curve(n=len(WALL_BY_DIST))


def _load_env_params():
    raw = _os.environ.get("WRONGWAY_PARAMS")
    if not raw:
        return
    try:
        if raw.lstrip().startswith("{"):
            set_params(_json.loads(raw))
        elif _os.path.isfile(raw):
            with open(raw, encoding="utf-8") as fh:
                set_params(_json.load(fh))
    except Exception:
        pass            # a bad override must never break the agent


_load_env_params()
